// Regla 3 en código: solo estas organizaciones pueden ser auto-verificadas.
// Ver 'Nota: qué SÍ y qué NO verifica solo' en el canvas para el porqué de cada una.
const ORGS_AUTO_CORROBORABLES = [
  'ABACO — Asociación de Bancos de Alimentos de Colombia',
];

const file = $input.first().json;
const contenido = Buffer.from(file.content, 'base64').toString('utf8');
const datos = JSON.parse(contenido);

return datos.orgs
  .filter(o => o.links && o.links[0] && o.links[0][1])
  .map(o => ({
    json: {
      org: o.name,
      url: o.links[0][1],
      autoCorrobora: ORGS_AUTO_CORROBORABLES.includes(o.name),
      payActual: o.pay || [],
      fileSha: file.sha,
      datosCompletosJSON: contenido,
    }
  }));

const crypto = require('crypto');
const origen = $('Expandir por organización').item.json;
const resp = $input.item.json;

// Si el nodo anterior falló de plano (sitio caído, DNS, timeout), resp trae .error
// en vez de .statusCode. Se trata igual que un fetch fallido: falla hacia 'inútil',
// nunca hacia 'dañino' (Regla 6) — simplemente no hay nada nuevo que verificar esta corrida.
const huboErrorDeRed = !!resp.error;
const statusCode = resp.statusCode;

let html = null;
if (!huboErrorDeRed && statusCode >= 200 && statusCode < 300) {
  html = typeof resp.body === 'string' ? resp.body : JSON.stringify(resp.body);
}
// (304 Not Modified, 4xx, 5xx o error de red -> html queda null -> no hay cambio que evaluar)

const textoPlano = html ? html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim() : '';
const hash = html ? crypto.createHash('sha256').update(textoPlano).digest('hex') : null;
const etagNuevo = (resp.headers && (resp.headers.etag || resp.headers.ETag)) || null;

return {
  json: {
    ...origen,
    statusCode: statusCode || null,
    htmlOriginal: html,
    textoPlano,
    hash,
    etagNuevo,
    fetchOk: html !== null,
  }
};

const item = $input.item.json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.hashes) staticData.hashes = {};

// OJO: acá solo se LEE. El hash nuevo se guarda al final, y solo si el commit
// a GitHub tuvo éxito — si no, la próxima corrida vuelve a intentar (ver nodo
// 'Guardar hashes nuevos').
const hashAnterior = staticData.hashes[item.org] || null;
const cambio = item.fetchOk && hashAnterior !== item.hash;

return { json: { ...item, hashAnterior, cambio } };

const origen = $('Comparar con corrida anterior').item.json;
const resp = $input.item.json;

let extraidos = [];
let parseoOk = true;
try {
  const texto = (resp.content && resp.content[0] && resp.content[0].text) || '[]';
  extraidos = JSON.parse(texto);
  if (!Array.isArray(extraidos)) throw new Error('la respuesta no fue un array');
} catch (e) {
  // Claude no devolvió JSON válido, o la llamada falló (resp.error). No se inventa
  // nada: se trata como 'sin datos nuevos que aplicar', el CORROBORAR de abajo
  // igual lo hubiera rechazado si hubiera intentado usarlo.
  extraidos = [];
  parseoOk = false;
}

return { json: { ...origen, extraidos, parseoOk } };

// Nodo Code, justo después de la extracción con IA (CLAUDE.md sección 5).
// Si el modelo inventó, corrigió o 'completó' un dígito, esto lo detecta.
// A propósito NUNCA hace throw: un fallo acá debe caer del lado 'inútil'
// (no se escribe el dato) y no tumbar la corrida de las demás organizaciones.
const item = $input.item.json;
const limpio = s => String(s).replace(/[\s.\-]/g, '');
const htmlLimpio = limpio(item.htmlOriginal || '');

const inventados = (item.extraidos || []).filter(
  c => c.value != null && !htmlLimpio.includes(limpio(c.value))
);
const corroboracionOk = item.parseoOk && inventados.length === 0;

return {
  json: {
    ...item,
    corroboracionOk,
    motivoCorroboracion: corroboracionOk ? null : ('Extracción inventó o no corroboró: ' + JSON.stringify(inventados)),
  }
};

// Mitad 'por organización' del fusible (CLAUDE.md sección 5): una página que
// vuelve sospechosamente vacía (bloqueo por bot, redirección, caída) es una
// señal de ESA organización específica. Tampoco hace throw — ver nota en CORROBORAR.
// El otro chequeo del fusible ('el cambio afecta >30% de los datos de pago') es
// GLOBAL, no por organización, y se evalúa más abajo en 'Reconstruir datos.json'
// — con solo 2 campos auto-corroborables hoy (ambos de ABACO), medirlo por
// organización haría que CUALQUIER cambio legítimo de un solo campo (ej. cambiaron
// de banco) se viera como '50%' y bloqueara todo, siempre. El fusible de tamaño
// de página SÍ tiene sentido por organización porque no depende de cuántos campos
// haya, así que se queda acá.
const item = $input.item.json;

if (!item.corroboracionOk) {
  return { json: { ...item, fusibleOk: false, motivoFusible: 'no aplica: la corroboración ya falló' } };
}

const motivos = [];
if ((item.htmlOriginal || '').length < 3000) motivos.push('el HTML descargado es sospechosamente pequeño');

return { json: { ...item, fusibleOk: motivos.length === 0, motivoFusible: motivos.join('; ') || null } };

// Punto de reunión de las dos ramas del IF: las que pasaron por Claude/CORROBORAR/
// FUSIBLE, y las que ni siquiera se intentaron (no autoCorrobora, o no cambió nada).
const item = $input.item.json;
const listoParaEscribir = item.corroboracionOk === true && item.fusibleOk === true;

let payNuevo = item.payActual;
let alerta = null;

if (listoParaEscribir) {
  // Regla 4: solo se actualiza el valor de campos que ya existían; nunca se
  // borra una fila. Si algún día se detecta que una cuenta ya no aparece,
  // eso se maneja aparte marcándola 'retirada' — no en este workflow todavía.
  payNuevo = item.payActual.map(([t, v, estado]) => {
    const encontrado = (item.extraidos || []).find(e => e.type === t);
    return (encontrado && encontrado.value) ? [t, encontrado.value, 'oficial'] : [t, v, estado];
  });
} else if (item.corroboracionOk === false) {
  alerta = `${item.org}: la extracción automática no coincidió con el HTML — revisa a mano. (${item.motivoCorroboracion})`;
} else if (item.fusibleOk === false) {
  alerta = `${item.org}: el fusible bloqueó el cambio — revisa a mano. (${item.motivoFusible})`;
} else if (item.cambio) {
  alerta = `${item.org}: la página cambió pero esta organización no está en la lista de auto-corroboración — revísala a mano.`;
}

return { json: { ...item, payNuevo, verificadoAhora: listoParaEscribir, alerta } };

const items = $input.all();
const base = JSON.parse(items[0].json.datosCompletosJSON); // igual en todos los items
const ahora = new Date().toISOString();

// ---- Fusible GLOBAL: % de los datos de pago del proyecto que cambiaría este commit ----
// (CLAUDE.md sección 5: 'el cambio afectaría más del 30% de los datos de pago').
// Se mide contra TODOS los campos de pago de datos.json, no solo los de esta
// organización — así un cambio normal de un solo campo no se ve artificialmente
// enorme. Con muy pocos campos auto-corroborables todavía, el % no es confiable
// (un solo cambio ya parece '50%'), así que el umbral solo se aplica cuando hay
// una muestra mínima; por debajo de eso, la corroboración por campo (Regla 3)
// sigue siendo la protección real.
const MUESTRA_MINIMA = 5;
const totalCamposPago = base.orgs.reduce((n, o) => n + (o.pay ? o.pay.length : 0), 0);
const camposCambiados = items.reduce((n, it) => {
  if (!it.json.verificadoAhora) return n;
  const diffs = it.json.payNuevo.filter((p, i) => p[1] !== it.json.payActual[i][1]).length;
  return n + diffs;
}, 0);
const pctGlobal = totalCamposPago ? camposCambiados / totalCamposPago : 0;
const fusibleGlobalSalta = totalCamposPago >= MUESTRA_MINIMA && pctGlobal > 0.30;

const cambios = [];
if (!fusibleGlobalSalta) {
  for (const it of items) {
    const j = it.json;
    const org = base.orgs.find(o => o.name === j.org);
    if (!org) continue;
    if (j.verificadoAhora) {
      org.pay = j.payNuevo;
      cambios.push(j.org);
    }
  }
}

// El campo más importante que escribe n8n (CLAUDE.md sección 5): se actualiza
// SIEMPRE, haya cambios de pago o no, incluso si el fusible global abortó los
// cambios de pago — así el aviso de frescura de la página sigue siendo honesto.
base.meta.verificado_el = ahora;
base.meta.revisado_por = 'n8n';

const alertas = items.filter(it => it.json.alerta).map(it => it.json.alerta);
if (fusibleGlobalSalta) {
  alertas.unshift(`FUSIBLE GLOBAL: el cambio afecta ${(pctGlobal * 100).toFixed(0)}% de los ${totalCamposPago} campos de pago del proyecto (>30%) — no se publicó NINGÚN cambio de pago esta corrida, revisa a mano.`);
}

return [{
  json: {
    contenidoNuevo: JSON.stringify(base, null, 2),
    fileSha: items[0].json.fileSha,
    orgsCambiadas: fusibleGlobalSalta ? [] : cambios,
    alertas,
    fusibleGlobalSalta,
    resultadosPorOrg: items.map(it => ({ org: it.json.org, hash: it.json.hash, cambio: it.json.cambio, verificadoAhora: it.json.verificadoAhora && !fusibleGlobalSalta })),
  }
}];

// Se guarda SOLO el hash de las organizaciones cuyo cambio realmente quedó
// escrito en el commit (verificadoAhora === true, ya ajustado por el fusible
// global). Para las demás — sin cambios, corroboración fallida, fusible por
// tamaño, o bloqueadas por el fusible global — NO se guarda nada, para que la
// próxima corrida (30 min después) las vuelva a detectar como 'cambio' y siga
// insistiendo/alertando hasta que alguien lo revise a mano. Nada queda
// 'olvidado' en silencio (CLAUDE.md sección 6: los dos fallos silenciosos).
const info = $('Reconstruir datos.json').first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.hashes) staticData.hashes = {};

for (const r of info.resultadosPorOrg) {
  if (r.hash && r.verificadoAhora) staticData.hashes[r.org] = r.hash;
}

return [{ json: { guardado: true, orgsCambiadas: info.orgsCambiadas, alertas: info.alertas, fusibleGlobalSalta: info.fusibleGlobalSalta } }];
